practice.solution:
package main

import "fmt"

func main() {
	age := 16
	if age >= 18 {
		fmt.Println("Adult")
	}
	if age < 13 {
		fmt.Println("Child")
	}
	if age == 16 {
		fmt.Println("Can learn to drive")
	}

	minor := age <= 17
	fmt.Println("minor:", minor)
	// 'Z' (90) sorts before 'a' (97)
	fmt.Println("Zoe" < "adam")
}

