practice.solution:
package main

import "fmt"

func main() {
	items := 38
	if rem := items % 6; rem != 0 {
		fmt.Println(rem, "items do not fit")
	}

	level := 5
	// the new level hides the outer one inside the if
	if level := level * 2; level > 8 {
		fmt.Println("inside:", level)
	}
	fmt.Println("outside:", level)
}
